#!/usr/bin/env node
// Generates db/init.sql from db/migrations/NNNN_*.sql.
//   node db/build-init.js          rewrite db/init.sql
//   node db/build-init.js --check  exit 1 if it is out of date (CI)
// The generated file is plain psql: each migration runs once (guarded with \if on the
// schema_migrations table), so `psql -f db/init.sql` is safe to run on every deploy.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const dir = path.join(__dirname, 'migrations');
const out = path.join(__dirname, 'init.sql');

const files = fs.readdirSync(dir).filter((f) => /^\d{4}_[a-z0-9_]+\.sql$/.test(f)).sort();
if (!files.length) throw new Error('no migrations found');
files.forEach((f, i) => {
  if (Number(f.slice(0, 4)) !== i + 1) throw new Error(`migrations must be numbered 0001.. without gaps (got ${f} at position ${i + 1})`);
});

const sha = (s) => crypto.createHash('sha256').update(s).digest('hex');
let sql = `-- GENERATED by db/build-init.js from db/migrations/*.sql: do not edit by hand.
-- Applies each numbered migration once; safe to run on every deploy.
CREATE TABLE IF NOT EXISTS schema_migrations (
  version    TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  checksum   TEXT NOT NULL,
  applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
`;
for (const f of files) {
  const version = f.slice(0, 4);
  const name = f.slice(5, -4);
  const body = fs.readFileSync(path.join(dir, f), 'utf8').replace(/\s+$/, '');
  const sum = sha(fs.readFileSync(path.join(dir, f), 'utf8'));
  sql += `
-- ===== migration ${version} ${name} =====
SELECT COALESCE((SELECT checksum FROM schema_migrations WHERE version = '${version}'), '') AS have \\gset
SELECT (:'have' = '') AS fresh, (:'have' <> '' AND :'have' <> '${sum}') AS drift \\gset
\\if :drift
  SELECT 'migration ${version} ${name} was edited after it was applied; add a new migration instead'::int;
\\endif
\\if :fresh
BEGIN;
${body}
INSERT INTO schema_migrations (version, name, checksum) VALUES ('${version}', '${name}', '${sum}');
COMMIT;
\\endif
`;
}

if (process.argv.includes('--check')) {
  if (!fs.existsSync(out) || fs.readFileSync(out, 'utf8') !== sql) {
    console.error('db/init.sql is out of date; run: node db/build-init.js');
    process.exit(1);
  }
  console.log(`db/init.sql matches db/migrations (${files.length} migrations)`);
} else {
  fs.writeFileSync(out, sql);
  console.log(`wrote db/init.sql from ${files.length} migration${files.length === 1 ? '' : 's'}`);
}
